define('NOREQUIREHTML',1);define('NOREQUIREMENU',1);require $_SERVER['DOCUMENT_ROOT'].'/main.inc.php';require_once __DIR__.'/../lib/main.lib.php';$id=GETPOSTINT('id');$variant=GETPOST('variant','alpha')==='safe'?'safe':'original';$sql='SELECT e.*,o.fk_user_assign FROM '.MAIN_DB_PREFIX.'cpo_qc_evidence e JOIN '.MAIN_DB_PREFIX.'cpo_operation o ON o.rowid=e.fk_operation AND o.entity=e.entity WHERE e.entity='.(int)$conf->entity.' AND e.rowid='.(int)$id." AND o.service_type='quality_control' AND o.status=1";$res=$db->query($sql);$row=$res?$db->fetch_object($res):null;$allowed=$row&&((int)$row->fk_user_assign===(int)$user->id||cpo_can($user,'qc_review')||!empty($user->admin));if(!$allowed)accessforbidden();$stored=$variant==='safe'?$row->safe_stored_name:$row->original_stored_name;$mime=$variant==='safe'?$row->safe_mime:$row->original_mime;$size=(int)($variant==='safe'?$row->safe_size:$row->original_size);$hash=$variant==='safe'?$row->safe_sha256:$row->original_sha256;$root=realpath(rtrim((string)$conf->chinaplanetoperations->dir_output,'/').'/qc/'.(int)$conf->entity.'/evidence');$path=$root&&$stored?realpath($root.'/'.$stored):false;if(!$path||is_link($path)||strpos($path,rtrim($root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)!==0||!is_file($path)||filesize($path)!==$size||!preg_match('/^[a-f0-9]{64}$/',(string)$hash)||!hash_equals((string)$hash,(string)hash_file('sha256',$path)))accessforbidden();header('Content-Type: '.($mime?:'application/octet-stream'));header('Content-Length: '.$size);header('Content-Disposition: '.($variant==='safe'?'inline':'attachment').'; filename="'.rawurlencode(basename($row->original_name)).'"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');readfile($path);exit;
